using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class FluidSurfaceOperations:RefCounted
{
    private static readonly Vector3I[] Corners={new(0,0,0),new(1,0,0),new(1,1,0),new(0,1,0),new(0,0,1),new(1,0,1),new(1,1,1),new(0,1,1)};private static readonly int[][] Tets={new[]{0,5,1,6},new[]{0,1,2,6},new[]{0,2,3,6},new[]{0,3,7,6},new[]{0,7,4,6},new[]{0,4,5,6}};
    private static Vector3 Vector(Vector3I value)=>new(value.X,value.Y,value.Z);private static Vector3I Truncate(Vector3 value)=>new((int)value.X,(int)value.Y,(int)value.Z);
    public Settings build(Vector3[] points,float[] foam,Settings values)
    {
        ulong started=Godot.Time.GetTicksUsec();double cell=values["cell"].AsDouble(),radius=values["spacing"].AsDouble()*1.65;var field=new Dictionary<Vector3I,double>();var gradients=new Dictionary<Vector3I,Vector3>();var froth=new Dictionary<Vector3I,double>();var cells=new HashSet<Vector3I>();var orderedCells=new List<Vector3I>();string error="";for(int i=0;i<points.Length;i++){var low=Truncate((points[i]-Vector3.One*(float)radius)/(float)cell)-Vector3I.One;var high=Truncate((points[i]+Vector3.One*(float)radius)/(float)cell)+Vector3I.One;for(int x=low.X;x<=high.X;x++)for(int y=low.Y;y<=high.Y;y++)for(int z=low.Z;z<=high.Z;z++){var key=new Vector3I(x,y,z);var delta=Vector(key)*(float)cell-points[i];double q=1-delta.LengthSquared()/(radius*radius);if(q<=0)continue;double weight=q*q*q;field[key]=field.GetValueOrDefault(key)+weight;gradients[key]=gradients.GetValueOrDefault(key)+delta*(float)(6*q*q/(radius*radius));froth[key]=froth.GetValueOrDefault(key)+weight*(i<foam.Length?foam[i]:0);}if(field.Count>180000){error="Surface budget exceeded. Increase spacing or choose Fast quality.";break;}}var mesh=new ArrayMesh();if(error.Length>0)return new Settings{["mesh"]=mesh,["error"]=error,["microseconds"]=Godot.Time.GetTicksUsec()-started};double iso=values["fluid_surface_level"].AsDouble();foreach(var entry in field){if(entry.Value<iso)continue;foreach(var offset in Corners){var key=entry.Key-offset;if(cells.Add(key))orderedCells.Add(key);}}var vertices=new List<Vector3>();var normals=new List<Vector3>();var colors=new List<Color>();var uv=new List<Vector2>();foreach(var key in orderedCells){var positions=new Vector3[8];var samples=new double[8];var normal=new Vector3[8];var white=new double[8];for(int i=0;i<8;i++){var at=key+Corners[i];double density=field.GetValueOrDefault(at);positions[i]=Vector(at)*(float)cell;samples[i]=density;normal[i]=gradients.GetValueOrDefault(at);white[i]=froth.GetValueOrDefault(at)/Math.Max(.00001,density);}foreach(var tet in Tets){var inside=new List<int>();var outside=new List<int>();foreach(int index in tet)if(samples[index]>=iso)inside.Add(index);else outside.Add(index);if(inside.Count==0||outside.Count==0)continue;var cuts=new List<(Vector3 Point,Vector3 Normal,double Foam)>();foreach(int a in inside)foreach(int b in outside){double t=Math.Clamp((iso-samples[a])/(samples[b]-samples[a]),0,1);cuts.Add((positions[a].Lerp(positions[b],(float)t),normal[a].Lerp(normal[b],(float)t).Normalized(),Mathf.Lerp(white[a],white[b],t)));}var triangles=cuts.Count==3?new[]{new[]{0,1,2}}:new[]{new[]{0,1,2},new[]{1,3,2}};foreach(var triangle in triangles){var cross=(cuts[triangle[1]].Point-cuts[triangle[0]].Point).Cross(cuts[triangle[2]].Point-cuts[triangle[0]].Point);var tri=triangle;if(cross.Dot(cuts[triangle[0]].Normal)>0)tri=new[]{triangle[0],triangle[2],triangle[1]};foreach(int index in tri){var cut=cuts[index];vertices.Add(cut.Point);normals.Add(cut.Normal);colors.Add(new Color((float)cut.Foam,0,0,1));uv.Add(new Vector2(cut.Point.X,cut.Point.Z));}}}}if(vertices.Count>0){var arrays=new GArray();arrays.Resize((int)Mesh.ArrayType.Max);arrays[(int)Mesh.ArrayType.Vertex]=vertices.ToArray();arrays[(int)Mesh.ArrayType.Normal]=normals.ToArray();arrays[(int)Mesh.ArrayType.Color]=colors.ToArray();arrays[(int)Mesh.ArrayType.TexUV]=uv.ToArray();mesh.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles,arrays);}return new Settings{["mesh"]=mesh,["error"]=error,["microseconds"]=Godot.Time.GetTicksUsec()-started,["vertices"]=vertices.Count,["grid"]=field.Count};
    }
}
